"""Optical-lever wire extension with zero correction and two estimators."""
from pathlib import Path
import json
import numpy as np
def analyze(experiment_dir):
 root=Path(experiment_dir);cfg=json.loads((root/'experiment.json').read_text(encoding='utf-8'));p=cfg['parameters'];budget=cfg['source_standard_uncertainties']
 d=np.genfromtxt(root/'data/diameters.csv',delimiter=',',names=True);load=np.genfromtxt(root/'data/loading.csv',delimiter=',',names=True)
 corrected=d['apparent_mm']-p['zero_offset_mm'];dm=float(corrected.mean());ua_d=float(np.std(corrected,ddof=1)/np.sqrt(6));x=(load['loading_mm']+load['unloading_mm'])/2;dx=x[5:]-x[:5];mean_dx=float(dx.mean());m=load['mass_kg'];xc=m-m.mean();yc=x-x.mean();k=float(xc@yc/(xc@xc));b=float(x.mean()-k*m.mean());r=float(xc@yc/np.sqrt((xc@xc)*(yc@yc)));res=x-k*m-b;uk=float(np.sqrt((res@res)/(len(m)-2)/(xc@xc)))
 g=p['gravity_m_s2'];L=p['wire_length_mm']/1000;H=p['mirror_distance_mm']/1000;D=p['lever_constant_mm']/1000
 pref=8*g*L*H/(np.pi*(dm/1000)**2*D);Ed=pref*5/(mean_dx/1000);Els=pref/(k/1000)
 geo=(budget['wire_length_mm']/p['wire_length_mm'])**2+(budget['mirror_distance_mm']/p['mirror_distance_mm'])**2+(2*budget['diameter_mm']/dm)**2+(budget['lever_constant_mm']/p['lever_constant_mm'])**2
 ud=Ed*np.sqrt(geo+(budget['mass_increment_kg']/5)**2+(budget['difference_mm']/mean_dx)**2);uls=Els*np.sqrt(geo+(uk/k)**2+(budget['mass_increment_kg']/5)**2)
 vals=[('mean_apparent_diameter',float(d['apparent_mm'].mean()),'mm','直径视值均值'),('mean_corrected_diameter',dm,'mm','零差修正直径均值'),('diameter_uncertainty_a',ua_d,'mm','直径均值A类不确定度'),('mean_extension_difference',mean_dx,'mm','五组逐差平均'),('fit_slope',k,'mm/kg','标尺质量拟合斜率'),('fit_intercept',b,'mm','标尺拟合截距'),('correlation',r,'1','标尺质量相关系数'),('slope_uncertainty',uk,'mm/kg','回归斜率标准误差'),('young_modulus_difference',Ed,'Pa','逐差杨氏模量'),('young_modulus_regression',Els,'Pa','回归杨氏模量'),('conditional_uncertainty_difference',ud,'Pa','逐差条件标准不确定度'),('conditional_uncertainty_regression',uls,'Pa','回归条件标准不确定度')]
 metrics={key:{'value':float(val),'unit':unit,'label':label} for key,val,unit,label in vals};metrics['young_modulus_difference']['uncertainty']=float(ud);metrics['young_modulus_regression']['uncertainty']=float(uls)
 headers=['序号','1','2','3','4','5'];headers2=['序号','6','7','8','9','10']
 common=lambda sl:[['质量视值 / kg',*m[sl].tolist()],['加力刻度 / mm',*load['loading_mm'][sl].tolist()],['减力刻度 / mm',*load['unloading_mm'][sl].tolist()],['平均刻度 / mm',*x[sl].tolist()]]
 return {'metrics':metrics,'tables':{'geometry':{'headers':['$L / \\mathrm{mm}$','$H / \\mathrm{mm}$','$D / \\mathrm{mm}$'],'rows':[[p['wire_length_mm'],p['mirror_distance_mm'],p['lever_constant_mm']]]},'diameters':{'headers':['序号','1','2','3','4','5','6','平均值 / mm'],'rows':[['直径视值 / mm',*d['apparent_mm'].tolist(),float(d['apparent_mm'].mean())],['修正直径 / mm',*corrected.tolist(),dm]]},'loading_first':{'headers':headers,'rows':common(slice(0,5))},'loading_second':{'headers':headers2,'rows':common(slice(5,10))+[['逐差 / mm',*dx.tolist()]]},'uncertainty':{'headers':['物理量','标准不确定度','物理量','标准不确定度'],'rows':[['$L / \\mathrm{mm}$',budget['wire_length_mm'],'$H / \\mathrm{mm}$',budget['mirror_distance_mm']],['$D / \\mathrm{mm}$',budget['lever_constant_mm'],'质量增量 / kg',budget['mass_increment_kg']],['$d / \\mathrm{mm}$',budget['diameter_mm'],'逐差 / mm',budget['difference_mm']]]}},'series':{'loading_fit':{'x':m.tolist(),'y':x.tolist(),'x_label':'拉力质量视值 / kg','y_label':'平均标尺刻度 / mm','fit':True},'diameter_sequence':{'x':list(range(1,7)),'y':corrected.tolist(),'x_label':'测量序号','y_label':'修正直径 / mm'}},'notes':['预算中一次性量及合成直径/逐差标准不确定度沿用源已给数值，来源误差限需核实。','质量增量校准误差在回归法中按u_m/5相对尺度项处理；几何与零差相关性未量化。']}
def explore(key,result):
 import plotly.graph_objects as go
 if key!='zero-offset':raise KeyError(key)
 apparent=result['metrics']['mean_apparent_diameter']['value'];dm=result['metrics']['mean_corrected_diameter']['value'];E=result['metrics']['young_modulus_regression']['value'];offset=np.linspace(.04,.08,101);curve=E*(dm/(apparent-offset))**2;zero=apparent-dm
 fig=go.Figure([go.Scatter(x=offset,y=curve,mode='lines',line={'color':'black'}),go.Scatter(x=[zero],y=[E],mode='markers',marker={'color':'black','size':11})]);fig.update_layout(template='plotly_white',font={'family':'Times New Roman, SimSun','size':18},width=900,height=580,xaxis_title='假设零差 / mm',yaxis_title='回归杨氏模量 / Pa',margin={'l':100,'r':30,'t':25,'b':150},showlegend=False,sliders=[{'active':55,'currentvalue':{'prefix':'假设零差 / mm：'},'steps':[{'label':f'{z:.4f}','method':'restyle','args':[{'x':[[float(z)]],'y':[[float(v)]]},[1]]} for z,v in zip(offset,curve)]}]);fig.update_xaxes(showline=True,linecolor='black',gridcolor='#e3e3e3');fig.update_yaxes(showline=True,linecolor='black',gridcolor='#e3e3e3');return fig
